1	//! zcr-test-ipm: one message from one process to another over an
2	//! `spsc::v4` ring in shared memory, the proof that the crate
3	//! does what it is for.
4	//!
5	//! - `zcr-test-ipm consumer` creates the region file, builds a
6	//!   pool and a ring in it, claims the consumer role, prints
7	//!   `ready`, and waits for one message.
8	//! - `zcr-test-ipm producer`, started after, maps the same file,
9	//!   attaches the pool and the ring, claims the producer role, and
10	//!   sends a random value with a checksum of it.
11	//! - The consumer checks the checksum, prints what it received,
12	//!   and exits 0, or non-zero on a bad checksum or a timeout.
13	//! - Everything is hard-coded, the path, the geometry, the ring's
14	//!   first segment, and the holder ids, since the one aim is to
15	//!   show a message crossing a process boundary intact.
16	//! - The MPSC mode, over an `mpsc::v3` ring in its own region file,
17	//!   shows producers and consumers coming and going across
18	//!   processes:
19	//!   - `zcr-test-ipm mpsc-consumer new|join <messages>` creates the
20	//!     region and the ring (`new`) or attaches (`join`), claims the
21	//!     consumer, prints `ready`, reads `messages` messages, sleeping
22	//!     on an empty ring, checks each checksum and each producer's
23	//!     order, releases the role, and prints each producer's first
24	//!     and last sequence number.
25	//!   - `zcr-test-ipm mpsc-producer <id> <count>` attaches, claims a
26	//!     producer, sends `count` messages numbered from 0, sleeping on
27	//!     a full ring, and releases.
28	//!   - `zcr-test-ipm mpsc-release` attaches and releases the ring,
29	//!     which fails while any role is held.
30	
31	#[cfg(target_os = "linux")]
32	use std::process::ExitCode;
33	
34	#[cfg(target_os = "linux")]
35	use zerocopy::{FromBytes, Immutable, IntoBytes, KnownLayout};
36	
37	/// The region file, in `/dev/shm` so the mapping is memory.
38	#[cfg(target_os = "linux")]
39	const PATH: &str = "/dev/shm/zcr-test-ipm-ring";
40	
41	/// Slot size: one cache line.
42	#[cfg(target_os = "linux")]
43	const SLOT: u32 = 64;
44	
45	/// Slots per segment.
46	#[cfg(target_os = "linux")]
47	const DEPTH: u32 = 8;
48	
49	/// Segments in the ring, each a buffer of the pool, which holds
50	/// exactly these.
51	#[cfg(target_os = "linux")]
52	const SEGMENTS: u32 = 2;
53	
54	/// The pool buffer index of the ring's segment 0. A fresh pool
55	/// hands out its buffers in a fixed order, so the consumer asserts
56	/// it and the producer attaches by it, and `Ring::attach` refuses
57	/// a region where it names no ring.
58	#[cfg(target_os = "linux")]
59	const FIRST_SEGMENT: u32 = 0;
60	
61	/// The consumer's holder id.
62	#[cfg(target_os = "linux")]
63	const CONSUMER_ID: u32 = 1;
64	
65	/// The producer's holder id.
66	#[cfg(target_os = "linux")]
67	const PRODUCER_ID: u32 = 2;
68	
69	/// How long the consumer waits for the message.
70	#[cfg(target_os = "linux")]
71	const WAIT: std::time::Duration = std::time::Duration::from_secs(10);
72	
73	/// The message: a value and a checksum of it, so a torn or
74	/// garbled message is caught.
75	#[cfg(target_os = "linux")]
76	#[derive(FromBytes, IntoBytes, KnownLayout, Immutable)]
77	#[repr(C)]
78	struct Msg {
79	    value: u64,
80	    checksum: u64,
81	}
82	
83	/// FNV-1a over the value's bytes.
84	#[cfg(target_os = "linux")]
85	fn checksum(value: u64) -> u64 {
86	    value
87	        .to_le_bytes()
88	        .iter()
89	        .fold(0xcbf2_9ce4_8422_2325, |h, &b| {
90	            (h ^ b as u64).wrapping_mul(0x0000_0100_0000_01b3)
91	        })
92	}
93	
94	/// A value nobody could have left in the region: the time and the
95	/// pid through one xorshift round.
96	#[cfg(target_os = "linux")]
97	fn random() -> u64 {
98	    // A clock before 1970 leaves the pid alone to vary it.
99	    let nanos = match std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH) {
100	        Ok(d) => d.as_nanos() as u64,
101	        Err(_) => 0,
102	    };
103	    let mut x = (nanos ^ ((std::process::id() as u64) << 32)) | 1;
104	    x ^= x << 13;
105	    x ^= x >> 7;
106	    x ^= x << 17;
107	    x
108	}
109	
110	/// Bytes the region holds: the pool's header and its segments.
111	#[cfg(target_os = "linux")]
112	fn region_len() -> usize {
113	    size_of::<zc_ring_x1::PoolHeader>()
114	        + SEGMENTS as usize * zc_ring_x1::spsc::v4::segment_size(SLOT, DEPTH) as usize
115	}
116	
117	/// Map the SPSC region file, as [`map_at`] does.
118	#[cfg(target_os = "linux")]
119	fn map(create: bool) -> Result<*mut u8, String> {
120	    map_at(PATH, region_len(), create)
121	}
122	
123	/// Map the region file at `path`, `len` bytes, shared, creating it
124	/// at its size when `create`, else opening the one a consumer
125	/// made.
126	///
127	/// - The mapping is never unmapped: it lives until the process
128	///   exits, so the pool and ring over it may borrow it for
129	///   `'static`.
130	#[cfg(target_os = "linux")]
131	fn map_at(path: &str, len: usize, create: bool) -> Result<*mut u8, String> {
132	    use std::os::fd::AsRawFd;
133	    let file = std::fs::OpenOptions::new()
134	        .read(true)
135	        .write(true)
136	        .create(create)
137	        .truncate(create)
138	        .open(path)
139	        .map_err(|e| format!("open {path}: {e}"))?;
140	    if create {
141	        file.set_len(len as u64)
142	            .map_err(|e| format!("size {path}: {e}"))?;
143	    } else if (file.metadata().map_err(|e| e.to_string())?.len() as usize) < len {
144	        return Err(format!("{path} is smaller than the region"));
145	    }
146	    // SAFETY: a fresh mapping of `len` bytes of an open file the
147	    // process may read and write, shared so the other process
148	    // sees the same memory. Closing the file keeps the mapping.
149	    let base = unsafe {
150	        libc::mmap(
151	            core::ptr::null_mut(),
152	            len,
153	            libc::PROT_READ | libc::PROT_WRITE,
154	            libc::MAP_SHARED,
155	            file.as_raw_fd(),
156	            0,
157	        )
158	    };
159	    if base == libc::MAP_FAILED {
160	        return Err(format!("mmap {path}: {}", std::io::Error::last_os_error()));
161	    }
162	    Ok(base as *mut u8)
163	}
164	
165	/// Build the ring, claim the consumer, and wait for one message.
166	#[cfg(target_os = "linux")]
167	fn consumer() -> Result<(), String> {
168	    use zc_ring_x1::{Pool, spsc::v4::Ring};
169	    let base = map(true)?;
170	    // SAFETY: the mapping is `region_len` bytes, page-aligned,
171	    // never unmapped, and this process's only view of it until the
172	    // producer attaches in another.
173	    let region = unsafe { core::slice::from_raw_parts_mut(base, region_len()) };
174	    let seg = zc_ring_x1::spsc::v4::segment_size(SLOT, DEPTH) as u32;
175	    let mut pool = Pool::init(region, seg, SEGMENTS).map_err(|e| format!("pool: {e:?}"))?;
176	    let ring = Ring::init(&mut pool, SLOT, DEPTH, SEGMENTS).map_err(|e| format!("ring: {e:?}"))?;
177	    if ring.first_segment() != FIRST_SEGMENT {
178	        return Err(format!(
179	            "ring's first segment is {}, not {FIRST_SEGMENT}",
180	            ring.first_segment()
181	        ));
182	    }
183	    let mut cons = ring
184	        .claim_consumer(CONSUMER_ID)
185	        .map_err(|e| format!("claim consumer: {e:?}"))?;
186	    println!("ready");
187	    use std::io::Write;
188	    std::io::stdout().flush().map_err(|e| e.to_string())?;
189	    let deadline = std::time::Instant::now() + WAIT;
190	    let msg = cons
191	        .reserve_slot_with::<Msg>(|_| {
192	            std::thread::sleep(std::time::Duration::from_millis(1));
193	            std::time::Instant::now() < deadline
194	        })
195	        .map_err(|_| format!("no message within {WAIT:?}"))?;
196	    let (value, sum) = (msg.value, msg.checksum);
197	    msg.release();
198	    if sum != checksum(value) {
199	        return Err(format!(
200	            "received value={value:#018x} checksum={sum:#018x}, bad, want {:#018x}",
201	            checksum(value)
202	        ));
203	    }
204	    println!("received value={value:#018x} checksum={sum:#018x} ok");
205	    Ok(())
206	}
207	
208	/// Attach the consumer's ring, claim the producer, and send one
209	/// message.
210	#[cfg(target_os = "linux")]
211	fn producer() -> Result<(), String> {
212	    use zc_ring_x1::{Pool, spsc::v4::Ring};
213	    let base = map(false)?;
214	    // SAFETY: the mapping is `region_len` bytes, shared and
215	    // writable, never unmapped, and this handle never allocates,
216	    // so the consumer's pool keeps its one allocator.
217	    let pool = unsafe { Pool::attach(base, region_len()) }.map_err(|e| format!("pool: {e:?}"))?;
218	    // SAFETY: FIRST_SEGMENT is the consumer's ring's segment 0 in
219	    // this pool, asserted there, and its segments are still the
220	    // ring's: the consumer allocates nothing else.
221	    let ring = unsafe { Ring::attach(&pool, FIRST_SEGMENT) }.map_err(|e| format!("ring: {e:?}"))?;
222	    let mut prod = ring
223	        .claim_producer(PRODUCER_ID)
224	        .map_err(|e| format!("claim producer: {e:?}"))?;
225	    let value = random();
226	    let mut slot = prod
227	        .reserve_slot_with::<Msg>(|_| false)
228	        .map_err(|_| "ring full".to_string())?;
229	    slot.value = value;
230	    slot.checksum = checksum(value);
231	    slot.commit();
232	    prod.release();
233	    println!(
234	        "sent value={value:#018x} checksum={:#018x}",
235	        checksum(value)
236	    );
237	    Ok(())
238	}
239	
240	/// The MPSC region file.
241	#[cfg(target_os = "linux")]
242	const MPSC_PATH: &str = "/dev/shm/zcr-test-ipm-mpsc";
243	
244	/// Segments in the MPSC ring, each a buffer of the pool, which
245	/// holds exactly these.
246	#[cfg(target_os = "linux")]
247	const MPSC_SEGMENTS: u32 = 3;
248	
249	/// The MPSC ring: segments switched, and sleeps on a futex whose
250	/// timeout turns a dead peer into a poll.
251	#[cfg(target_os = "linux")]
252	type MpscRing = zc_ring_x1::mpsc::v3::MpscRing<
253	    'static,
254	    zc_ring_x1::mpsc::v3::Multi,
255	    zc_ring_x1::wake::Futex<10>,
256	>;
257	
258	/// An MPSC message: its producer, its number in that producer's
259	/// stream, a value, and a checksum over all three.
260	#[cfg(target_os = "linux")]
261	#[derive(FromBytes, IntoBytes, KnownLayout, Immutable)]
262	#[repr(C)]
263	struct MpscMsg {
264	    producer: u64,
265	    seq: u64,
266	    value: u64,
267	    checksum: u64,
268	}
269	
270	/// The checksum of an MPSC message's three fields.
271	#[cfg(target_os = "linux")]
272	fn mpsc_checksum(producer: u64, seq: u64, value: u64) -> u64 {
273	    checksum(producer ^ checksum(seq ^ checksum(value)))
274	}
275	
276	/// Bytes the MPSC region holds: the pool's header and its segments.
277	#[cfg(target_os = "linux")]
278	fn mpsc_region_len() -> usize {
279	    size_of::<zc_ring_x1::PoolHeader>()
280	        + MPSC_SEGMENTS as usize * zc_ring_x1::mpsc::v3::segment_size(SLOT, DEPTH) as usize
281	}
282	
283	/// Attach the MPSC region's pool and ring.
284	#[cfg(target_os = "linux")]
285	fn mpsc_attach() -> Result<MpscRing, String> {
286	    let base = map_at(MPSC_PATH, mpsc_region_len(), false)?;
287	    // SAFETY: the mapping is the region's length, shared and
288	    // writable, never unmapped, and this handle never allocates.
289	    let pool = unsafe { zc_ring_x1::Pool::attach(base, mpsc_region_len()) }
290	        .map_err(|e| format!("pool: {e:?}"))?;
291	    // The pool handle lives as long as the process, as the
292	    // mapping does.
293	    let pool = Box::leak(Box::new(pool));
294	    // SAFETY: FIRST_SEGMENT is the ring's segment 0 in this pool,
295	    // asserted by the consumer that made it, and its segments are
296	    // the ring's until a release, after which the magic is gone.
297	    unsafe { MpscRing::attach(pool, FIRST_SEGMENT) }.map_err(|e| format!("ring: {e:?}"))
298	}
299	
300	/// Create (`new`) or attach (`join`) the MPSC ring, claim the
301	/// consumer, read `messages` messages, and release.
302	#[cfg(target_os = "linux")]
303	fn mpsc_consumer(how: &str, messages: u64) -> Result<(), String> {
304	    let ring = match how {
305	        "new" => {
306	            let base = map_at(MPSC_PATH, mpsc_region_len(), true)?;
307	            // SAFETY: the mapping is the region's length,
308	            // page-aligned, never unmapped, and this process's only
309	            // view of it until another attaches.
310	            let region = unsafe { core::slice::from_raw_parts_mut(base, mpsc_region_len()) };
311	            let seg = zc_ring_x1::mpsc::v3::segment_size(SLOT, DEPTH) as u32;
312	            let pool = zc_ring_x1::Pool::init(region, seg, MPSC_SEGMENTS)
313	                .map_err(|e| format!("pool: {e:?}"))?;
314	            let pool = Box::leak(Box::new(pool));
315	            let ring = MpscRing::init(pool, SLOT, DEPTH, MPSC_SEGMENTS)
316	                .map_err(|e| format!("ring: {e:?}"))?;
317	            if ring.first_segment() != FIRST_SEGMENT {
318	                return Err(format!(
319	                    "ring's first segment is {}, not {FIRST_SEGMENT}",
320	                    ring.first_segment()
321	                ));
322	            }
323	            ring
324	        }
325	        "join" => mpsc_attach()?,
326	        _ => return Err("mpsc-consumer takes new or join".to_string()),
327	    };
328	    let mut cons = ring
329	        .claim_consumer()
330	        .map_err(|e| format!("claim consumer: {e:?}"))?;
331	    println!("ready");
332	    use std::io::Write;
333	    std::io::stdout().flush().map_err(|e| e.to_string())?;
334	    // Each producer's first and last number seen, in order.
335	    let mut seen: std::collections::BTreeMap<u64, (u64, u64)> = Default::default();
336	    let deadline = std::time::Instant::now() + WAIT;
337	    for n in 0..messages {
338	        let msg = cons
339	            .reserve_slot_wait::<MpscMsg>(|_| std::time::Instant::now() < deadline)
340	            .map_err(|_| format!("message {n} not within {WAIT:?}"))?;
341	        let (p, seq, value, sum) = (msg.producer, msg.seq, msg.value, msg.checksum);
342	        msg.release();
343	        if sum != mpsc_checksum(p, seq, value) {
344	            return Err(format!("message {n}: bad checksum from producer {p}"));
345	        }
346	        match seen.get_mut(&p) {
347	            Some((_, last)) if seq == *last + 1 => *last = seq,
348	            Some((_, last)) => {
349	                return Err(format!("producer {p}: {seq} after {last}"));
350	            }
351	            None => {
352	                seen.insert(p, (seq, seq));
353	            }
354	        }
355	    }
356	    cons.release();
357	    for (p, (first, last)) in &seen {
358	        println!("received producer={p} first={first} last={last}");
359	    }
360	    println!("received {messages} ok");
361	    Ok(())
362	}
363	
364	/// Attach the MPSC ring, claim a producer, send `count` messages
365	/// numbered from 0, and release.
366	#[cfg(target_os = "linux")]
367	fn mpsc_producer(id: u64, count: u64) -> Result<(), String> {
368	    let ring = mpsc_attach()?;
369	    let prod = ring
370	        .claim_producer()
371	        .map_err(|e| format!("claim producer: {e:?}"))?;
372	    // Each message may wait up to WAIT for room, asleep on the futex from the first full look.
373	    let sleep_time = zc_ring_x1::microsecs_to_ticks(WAIT.as_micros() as u64);
374	    for seq in 0..count {
375	        let value = random() ^ seq;
376	        prod.send_spin_sleep::<MpscMsg>(zc_ring_x1::Ticks::ZERO, sleep_time, |m| {
377	            m.producer = id;
378	            m.seq = seq;
379	            m.value = value;
380	            m.checksum = mpsc_checksum(id, seq, value);
381	        })
382	        .map_err(|_| format!("message {seq} not sent within {WAIT:?}"))?;
383	    }
384	    prod.release();
385	    println!("sent producer={id} count={count}");
386	    Ok(())
387	}
388	
389	/// Attach the MPSC ring and release it.
390	#[cfg(target_os = "linux")]
391	fn mpsc_release() -> Result<(), String> {
392	    let base = map_at(MPSC_PATH, mpsc_region_len(), false)?;
393	    // SAFETY: as in mpsc_attach, and the release frees buffers,
394	    // which any process may do.
395	    let pool = unsafe { zc_ring_x1::Pool::attach(base, mpsc_region_len()) }
396	        .map_err(|e| format!("pool: {e:?}"))?;
397	    // SAFETY: as in mpsc_attach.
398	    let ring =
399	        unsafe { MpscRing::attach(&pool, FIRST_SEGMENT) }.map_err(|e| format!("ring: {e:?}"))?;
400	    ring.release_ring(&pool)
401	        .map_err(|e| format!("release: {e:?}"))?;
402	    println!("released");
403	    Ok(())
404	}
405	
406	/// The `n`th argument as a number.
407	#[cfg(target_os = "linux")]
408	fn arg_num(n: usize) -> Result<u64, String> {
409	    std::env::args()
410	        .nth(n)
411	        .ok_or_else(|| format!("argument {n} missing"))?
412	        .parse()
413	        .map_err(|e| format!("argument {n}: {e}"))
414	}
415	
416	#[cfg(target_os = "linux")]
417	fn main() -> ExitCode {
418	    let role = std::env::args().nth(1);
419	    let run = match role.as_deref() {
420	        Some("consumer") => consumer(),
421	        Some("producer") => producer(),
422	        Some("mpsc-consumer") => std::env::args()
423	            .nth(2)
424	            .ok_or_else(|| "mpsc-consumer takes new or join".to_string())
425	            .and_then(|how| mpsc_consumer(&how, arg_num(3)?)),
426	        Some("mpsc-producer") => arg_num(2).and_then(|id| mpsc_producer(id, arg_num(3)?)),
427	        Some("mpsc-release") => mpsc_release(),
428	        _ => Err(
429	            "usage: zcr-test-ipm consumer | producer | mpsc-consumer new|join <messages> \
430	             | mpsc-producer <id> <count> | mpsc-release"
431	                .to_string(),
432	        ),
433	    };
434	    match run {
435	        Ok(()) => ExitCode::SUCCESS,
436	        Err(e) => {
437	            eprintln!("zcr-test-ipm: {e}");
438	            ExitCode::FAILURE
439	        }
440	    }
441	}
442	
443	#[cfg(not(target_os = "linux"))]
444	fn main() {
445	    eprintln!("zcr-test-ipm: Linux only, it maps /dev/shm");
446	    std::process::exit(1);
447	}
