//! The inter-process message: `zcr-test-ipm consumer` and
//! `zcr-test-ipm producer` as two processes, the consumer first,
//! and the value the producer sent is the value the consumer
//! received with its checksum verified.
//!
//! - Twenty rounds in one test, since the two share one
//!   hard-coded region file and must not run beside another pair.
//! - Each round prints the producer's and the consumer's lines,
//!   which `-- --show-output` displays.

#![cfg(target_os = "linux")]

use std::io::{BufRead, BufReader};
use std::process::{Command, Stdio};

/// The app, under its cycle name or its landed one.
fn app() -> &'static str {
    option_env!("CARGO_BIN_EXE_zcr-test-ipm")
        .or(option_env!("CARGO_BIN_EXE_zcr-test-ipm-dev"))
        .expect("the zcr-test-ipm binary is built for integration tests")
}

/// The value field of a `sent` or `received` line.
fn value(line: &str) -> &str {
    line.split_whitespace()
        .find(|w| w.starts_with("value="))
        .unwrap_or_else(|| panic!("no value in {line:?}"))
}

#[test]
fn one_message_crosses_between_processes() {
    for round in 0..20 {
        let mut consumer = Command::new(app())
            .arg("consumer")
            .stdout(Stdio::piped())
            .spawn()
            .unwrap();
        let mut lines = BufReader::new(consumer.stdout.take().unwrap()).lines();
        assert_eq!(lines.next().unwrap().unwrap(), "ready", "round {round}");

        let producer = Command::new(app()).arg("producer").output().unwrap();
        assert!(producer.status.success(), "round {round}: {producer:?}");
        let sent = String::from_utf8(producer.stdout).unwrap();

        let received = lines.next().unwrap().unwrap();
        assert!(consumer.wait().unwrap().success(), "round {round}");
        assert!(sent.starts_with("sent "), "round {round}: {sent:?}");
        assert!(received.ends_with(" ok"), "round {round}: {received:?}");
        assert_eq!(value(&sent), value(&received), "round {round}");
        // Shown by `cargo test --test ipm -- --show-output`.
        println!("round {round:2}: {} | {received}", sent.trim_end());
    }
}

/// Spawn the app with `args`, its stdout piped.
fn spawn(args: &[&str]) -> std::process::Child {
    Command::new(app())
        .args(args)
        .stdout(Stdio::piped())
        .spawn()
        .unwrap()
}

/// Wait for a child and return its stdout, asserting it succeeded.
fn finish(child: std::process::Child, what: &str) -> String {
    let out = child.wait_with_output().unwrap();
    assert!(out.status.success(), "{what}: {out:?}");
    String::from_utf8(out.stdout).unwrap()
}

/// Spawn an MPSC consumer and wait for its `ready` line, returning
/// the child and the rest of its output to come.
fn mpsc_consumer(how: &str, messages: u64) -> std::process::Child {
    let mut child = spawn(&["mpsc-consumer", how, &messages.to_string()]);
    let mut ready = String::new();
    BufReader::new(child.stdout.as_mut().unwrap())
        .read_line(&mut ready)
        .unwrap();
    assert_eq!(ready.trim_end(), "ready", "{how} consumer");
    child
}

/// Each producer's first and last number from a consumer's output.
fn ranges(out: &str) -> std::collections::BTreeMap<u64, (u64, u64)> {
    out.lines()
        .filter(|l| l.starts_with("received producer="))
        .map(|l| {
            let field = |name: &str| -> u64 {
                l.split_whitespace()
                    .find_map(|w| w.strip_prefix(name))
                    .unwrap()
                    .parse()
                    .unwrap()
            };
            (field("producer="), (field("first="), field("last=")))
        })
        .collect()
}

#[test]
fn mpsc_producers_and_consumers_come_and_go_between_processes() {
    const EACH: u64 = 20_000;
    // A consumer makes the ring, and a release while it holds the
    // consumer role is refused.
    let first = mpsc_consumer("new", EACH);
    let refused = Command::new(app()).arg("mpsc-release").output().unwrap();
    assert!(!refused.status.success());
    assert!(String::from_utf8_lossy(&refused.stderr).contains("RingInUse"));

    // Two producer processes at once, and the first consumer reads
    // half of what they send, releases, and exits, while they wait
    // on the full ring for the next.
    let p0 = spawn(&["mpsc-producer", "0", &EACH.to_string()]);
    let p1 = spawn(&["mpsc-producer", "1", &EACH.to_string()]);
    let first = finish(first, "first consumer");
    let second = mpsc_consumer("join", EACH);
    finish(p0, "producer 0");
    finish(p1, "producer 1");
    let second = finish(second, "second consumer");

    // The second consumer continued each producer's stream exactly
    // where the first stopped, and together they read everything.
    let (a, b) = (ranges(&first), ranges(&second));
    for p in 0..2u64 {
        let (a_first, a_last) = a.get(&p).copied().unwrap_or((0, u64::MAX));
        let (b_first, b_last) = b[&p];
        assert_eq!(a_first, 0, "producer {p}");
        assert_eq!(b_first, a_last.wrapping_add(1), "producer {p}");
        assert_eq!(b_last, EACH - 1, "producer {p}");
    }

    // A producer that comes after the others have gone, to a third
    // consumer, and then the ring, no role held, is released, and
    // a producer can no longer join it.
    let third = mpsc_consumer("join", 100);
    finish(spawn(&["mpsc-producer", "2", "100"]), "producer 2");
    let third = finish(third, "third consumer");
    assert_eq!(ranges(&third)[&2], (0, 99));
    finish(spawn(&["mpsc-release"]), "release");
    let late = Command::new(app())
        .args(["mpsc-producer", "3", "1"])
        .output()
        .unwrap();
    assert!(!late.status.success());
    assert!(String::from_utf8_lossy(&late.stderr).contains("BadMagic"));
}

//! MPSC v4 ring: many producers send messages to one consumer through a ring of slots in shared
//! memory, so the producers and the consumer may be threads of one process or separate processes.
//! v4 is v3 with a consumer that receives as a producer sends, and with plainer names. v3 stays as
//! built to measure against.
//!
//! # Words
//!
//! Each word has one meaning in these docs.
//!
//! - Ring: the queue. It lives in buffers taken from the application's [`Pool`], and an
//!   [`MpscRing`] is a handle to it.
//! - Message: the data a producer has for the consumer, of any size.
//! - Id: a small value that says where a message is. The crate's id is a [`Desc`](crate::Desc),
//!   which names a pool and a buffer in it.
//! - Slot: one entry of the ring, small and of a fixed size set at [`MpscRing::init`], holding a
//!   value of the type `T` the two sides agree on. In the typical use the message is written into a
//!   pool buffer and the slot holds its id, so the ring carries the id and the message is never
//!   copied, which is what zero-copy means here. That works wherever both sides can reach the
//!   message's pool. A message small enough to fit a slot may be the slot's value itself, with no
//!   pool.
//! - Segment: a run of slots in one pool buffer. A [`Multi`] ring has several and moves on to a
//!   free one when the current one fills, and a [`Single`] ring has one.
//! - Producer: an [`MpscProducer`], from [`MpscRing::producer`]. It sends.
//! - Consumer: the ring's one [`MpscConsumer`], from [`MpscRing::consumer`]. It receives.
//! - Role: being a producer, or the consumer, of a ring. A role is held from `producer()` or
//!   `consumer()` until that endpoint's `release`, and [`MpscRing::release_ring`] gives the ring
//!   back to the pool once no role is held.
//! - Send: `send` takes the next free slot, a closure writes the slot's value there, the id or the
//!   message, and `send` commits the slot, which is when the consumer can read it.
//! - Receive: `recv` takes the oldest committed slot, a closure reads its value in place, and
//!   `recv` frees the slot for the producers.
//! - Policy: a [`WaitPolicy`], what a send asks at a full ring and a receive asks at an empty one:
//!   look again, sleep first, or give up. `send_spin`, `recv_spin`, `send_spin_sleep`, and
//!   `recv_spin_sleep` come with a policy already written.
//! - Wait: `W`, the ring's choice of how its endpoints wait, a [`Waits`]: [`SpinOnly`], `Sleep`
//!   over a wake such as `Futex`, or `SpinOrSleep` over one. See [Waits](#waits).
//!
//! # Use
//!
//! 1. Make a ring over a pool with [`MpscRing::init`], or join one another process made with
//!    [`MpscRing::attach`].
//! 2. Take a role: `ring.producer()` in each sender, `ring.consumer()` in the receiver.
//! 3. Send with `producer.send(policy, |msg| ...)` and receive with `consumer.recv(policy, |msg|
//!    ...)`, or their `_spin` and `_spin_sleep` forms.
//! 4. Give each role back with `release`, then the ring with `release_ring`.
//!
//! A complete program in two threads, pool to release, is `examples/`'s [guide_mpsc_v4.rs]: the
//! typical zero-copy use, where each message is written into a buffer of a message pool and the
//! ring carries the buffer's id.
//!
//! [guide_mpsc_v4.rs]: https://github.com/winksaville/zc-ring-x1/blob/main/examples/guide_mpsc_v4.rs
//!
//! # Waits
//!
//! How the endpoints of a ring may wait is the ring's choice, not each endpoint's, since an
//! endpoint can sleep only if every other endpoint checks for sleepers, and those checks cost the
//! endpoints that are awake. The choice is the ring's second type parameter, beside its mode, and a
//! ring reads as one of these six:
//!
//! ```text
//! MpscRing<Multi, SpinOnly>               MpscRing<Single, SpinOnly>
//! MpscRing<Multi, Sleep<Futex>>           MpscRing<Single, Sleep<Futex>>
//! MpscRing<Multi, SpinOrSleep<Futex>>     MpscRing<Single, SpinOrSleep<Futex>>
//! ```
//!
//! The mode and the wait are chosen apart: [`Multi`], several segments, or [`Single`], one, goes
//! with any of the three waits. `MpscRing` with neither written is `MpscRing<Multi, SpinOnly>`, and
//! the endpoints take the ring's two choices, `MpscProducer<Single, Sleep<Futex>>`.
//!
//! - [`SpinOnly`]: an endpoint spins, for some time or forever, and if the time passes before it
//!   succeeds it returns `Err(Full)` or `Err(Empty)`. The ring offers the `_spin` forms. Nothing
//!   sleeps, so nothing checks for a sleeper, and the choice costs nothing.
//! - [`Sleep<Futex>`](crate::wake::Sleep): an endpoint spins for some time, which may be none, then
//!   optionally sleeps on a waiter object, here a futex, for some further time or forever, and if
//!   both times pass before it succeeds it returns `Err(Full)` or `Err(Empty)`. The ring offers the
//!   `_spin_sleep` forms, and every endpoint pays for the checks below.
//! - [`SpinOrSleep<Futex>`](crate::wake::SpinOrSleep): each endpoint either waits as over `Sleep`,
//!   or spins without end and never sleeps. The ring offers both forms, and the spinners pay for
//!   the checks that wake the sleepers.
//!
//! `SpinOrSleep<Futex>` is `Sleep<Futex>`'s code exactly. Its name is how a caller says the mix is
//! on purpose. `Futex` is what a sleeper sleeps on, a [`Wake`](crate::wake::Wake), and is not a
//! choice by itself, so `MpscRing<Multi, Futex>` does not compile. The general `send` and `recv`
//! take any policy on any ring, so the list is a signpost and not a wall, and a `spin_time` of
//! `Ticks::FOREVER` is a value, so a spin without end through `_spin_sleep` still compiles on a
//! ring over `Sleep`.
//!
//! ## The checks, and what they cost
//!
//! An endpoint asleep is woken by the other side, so on a ring whose wake sleeps the side that is
//! awake has to look for a sleeper, on every message path, whether or not anyone ever sleeps:
//!
//! - A producer, after each commit, tests whether the consumer said it was going to sleep. The flag
//!   comes back with the word the send already read, so the check is a test and a branch, and a
//!   wake call when the flag is set.
//! - The consumer, at every half segment of messages read, at each segment it gives back, and
//!   before it sleeps itself, makes its reads visible with a full memory fence and then reads the
//!   count of producers asleep on a full ring, waking them when there are any.
//!
//! So the cost is a branch on each send, a fence and a load every half segment of receives, and
//! what those few instructions do to the loops around them. What we have measured, with every
//! endpoint spinning and none asleep, a ring that checks against the same ring that does not:
//!
//! - Streaming, one producer, one machine: from no difference we could measure to about 28% more
//!   time a message, the largest on two hyperthreads of one core. In a few rows, at segments of one
//!   slot, the ring that checks was the faster by up to 14%.
//! - Round trips with one message in flight, another machine, two hyperthreads of one core: about
//!   7% more.
//!
//! The cost can be large or absent, and it moves with many things: which cores the endpoints run on
//! and whether they share a core or a cache, the ring's depth, how many producers there are, the
//! machine, the build profile, and how the producer's loop and the consumer's fall into step. Every
//! situation is different and has to be measured. In most of what we have measured, spinning over
//! `SpinOnly` has been the quickest, at the price of a core kept busy by each endpoint that waits.
//!
//! The measurements are in the design note, [MPSC v3 measured] and [MPSC v3 across machines and
//! build profiles], taken on v3, whose message paths v4 copies.
//!
//! [MPSC v3 measured]: https://github.com/winksaville/zc-ring-x1/blob/main/notes/ring-buffer-design.md#mpsc-v3-measured
//! [MPSC v3 across machines and build profiles]: https://github.com/winksaville/zc-ring-x1/blob/main/notes/ring-buffer-design.md#mpsc-v3-across-machines-and-build-profiles
//!
//! ## What compiles
//!
//! A sleep on a ring over [`SpinOnly`] does not compile:
//!
//! ```compile_fail
//! use zc_ring_x1::mpsc::v4::{MpscConsumer, Single};
//! use zc_ring_x1::{Ticks, wake::SpinOnly};
//! fn sleeps(consumer: &mut MpscConsumer<'_, Single, SpinOnly>) {
//!     let _ = consumer.recv_spin_sleep(Ticks::ZERO, Ticks::FOREVER, |id: &u64| *id);
//! }
//! ```
//!
//! Nor does a spin alone on a ring over `Sleep`:
//!
//! ```compile_fail
//! use zc_ring_x1::mpsc::v4::{MpscProducer, Multi};
//! use zc_ring_x1::{Ticks, wake::{Futex, Sleep}};
//! fn spins(producer: &MpscProducer<'_, Multi, Sleep<Futex>>) {
//!     let _ = producer.send_spin(Ticks::FOREVER, |id: &mut u64| *id = 1);
//! }
//! ```
//!
//! Nor a ring over a wake with no choice made:
//!
//! ```compile_fail
//! use zc_ring_x1::mpsc::v4::{MpscProducer, Multi};
//! use zc_ring_x1::wake::Futex;
//! fn no_choice(_producer: &MpscProducer<'_, Multi, Futex>) {}
//! ```
//!
//! Each compiles on a ring whose choice offers it, in either mode:
//!
//! ```
//! # #[cfg(target_os = "linux")]
//! # {
//! use zc_ring_x1::mpsc::v4::{MpscConsumer, MpscProducer, Multi, Single};
//! use zc_ring_x1::wake::{Futex, Sleep, SpinOnly, SpinOrSleep};
//! use zc_ring_x1::Ticks;
//! fn spins(producer: &MpscProducer<'_, Single, SpinOnly>) {
//!     let _ = producer.send_spin(Ticks::FOREVER, |id: &mut u64| *id = 1);
//! }
//! fn sleeps(consumer: &mut MpscConsumer<'_, Multi, Sleep<Futex>>) {
//!     let _ = consumer.recv_spin_sleep(Ticks::ZERO, Ticks::FOREVER, |id: &u64| *id);
//! }
//! fn either(producer: &MpscProducer<'_, Single, SpinOrSleep<Futex>>) {
//!     let _ = producer.send_spin(Ticks::FOREVER, |id: &mut u64| *id = 1);
//!     let _ = producer.send_spin_sleep(Ticks::ZERO, Ticks::FOREVER, |id: &mut u64| *id = 1);
//! }
//! # }
//! ```
//!
//! # What v4 changes from v3
//!
//! - Its own magic, so a v3 ring and a v4 ring never attach to each other.

