233	/// Discover the placements for the pinned 2t runs from
234	/// /sys/devices/system/cpu, each starting at `base`, in the
235	/// measurement tools' order, and only those the machine has:
236	///
237	/// - `CCX`: `base` and another core sharing its L3, the near
238	///   cross-core handoff.
239	/// - `x-CCX`: `base` and a core outside its L3, the far one.
240	/// - `SMT`: `base` and its SMT sibling, one core's two
241	///   cpus sharing L1 and L2, the cheapest.
242	/// - `unpinned`: the scheduler's choice, always present.
243	#[cfg(target_os = "linux")]
244	fn discover_placements(base: usize) -> Vec<Placement> {
245	    let siblings = siblings_of(base);
246	    let online = online_cpus();
247	    let l3 = std::fs::read_to_string(format!(
248	        "/sys/devices/system/cpu/cpu{base}/cache/index3/shared_cpu_list"
249	    ))
250	    .ok()
251	    .map(|s| parse_cpu_list(&s))
252	    .unwrap_or_else(|| siblings.clone());
253	    let mut v = Vec::new();
254	    if let Some(c) = quiet_first(&l3)
255	        .into_iter()
256	        .find(|&c| c != base && !siblings.contains(&c))
257	    {
258	        v.push(Placement {
259	            label: format!("{base},{c} CCX"),
260	            pin: Some((base, c)),
261	        });
262	    }
263	    if let Some(c) = quiet_first(&online).into_iter().find(|c| !l3.contains(c)) {
264	        v.push(Placement {
265	            label: format!("{base},{c} x-CCX"),
266	            pin: Some((base, c)),
267	        });
268	    }
269	    if let Some(c) = siblings.iter().copied().find(|&c| c != base) {
270	        v.push(Placement {
271	            label: format!("{base},{c} SMT"),
272	            pin: Some((base, c)),
273	        });
274	    }
275	    v.push(Placement {
276	        label: "unpinned".to_string(),
277	        pin: None,
278	    });
279	    v
280	}
