361	/// Pin the calling thread to `cpu` via sched_setaffinity.
362	/// Panics on failure (a demo run with a silently ignored pin
363	/// would report a mislabeled number).
364	#[cfg(target_os = "linux")]
365	fn pin_to_cpu(cpu: usize) {
366	    // SAFETY: cpu_set_t is a plain bitmask. CPU_ZERO/CPU_SET
367	    // initialize it fully before sched_setaffinity reads it.
368	    unsafe {
369	        let mut set: libc::cpu_set_t = std::mem::zeroed();
370	        libc::CPU_ZERO(&mut set);
371	        libc::CPU_SET(cpu, &mut set);
372	        let rc = libc::sched_setaffinity(0, size_of::<libc::cpu_set_t>(), &set);
373	        assert_eq!(rc, 0, "sched_setaffinity({cpu}) failed");
374	    }
375	}
