383	/// Bind one SPSC ring's `$producer` and `$consumer`, one-line
384	/// slots at `$depth`, its storage held in `$store` (and, for a
385	/// ring of segments, its pool in `$pool`) so it outlives them.
386	///
387	/// - `single $ring, $size`: a ring over one region sized by
388	///   `$size(slot_size, depth)`.
389	/// - `segmented $segments`: a v3 ring of `$segments` segments,
390	///   each `$depth` slots, over a pool holding exactly those
391	///   segments.
392	/// - `segmented_roles $segments`: the same over a v4 ring, whose
393	///   endpoints are taken by name.
394	macro_rules! spsc_pair {
395	    ($producer:ident, $consumer:ident, $store:ident, $pool:ident, $depth:expr,
396	     single $ring:path, $size:path) => {
397	        let slot = CACHE_LINE_SIZE as u32;
398	        let mut $store = region($size(slot, $depth));
399	        let (mut $producer, mut $consumer) = <$ring>::init($store.as_mut_bytes(), slot, $depth)
400	            .unwrap() // OK: the region is sized by the ring's own size function and line-aligned
401	            .split();
402	    };
403	    ($producer:ident, $consumer:ident, $store:ident, $pool:ident, $depth:expr,
404	     segmented $segments:expr) => {
405	        let slot = CACHE_LINE_SIZE as u32;
406	        let buf = zc_ring_x1::spsc::v3::segment_size(slot, $depth);
407	        let mut $store =
408	            region(size_of::<zc_ring_x1::PoolHeader>() as u64 + buf * $segments as u64);
409	        let mut $pool = Pool::init($store.as_mut_bytes(), buf as u32, $segments)
410	            .unwrap(); // OK: the region is sized for exactly the segments and line-aligned
411	        let (mut $producer, mut $consumer) =
412	            zc_ring_x1::spsc::v3::Ring::init(&mut $pool, slot, $depth, $segments)
413	                .unwrap() // OK: the pool holds exactly the segments, sized by segment_size
414	                .split();
415	    };
416	    ($producer:ident, $consumer:ident, $store:ident, $pool:ident, $depth:expr,
417	     segmented_roles $segments:expr) => {
418	        let slot = CACHE_LINE_SIZE as u32;
419	        let buf = zc_ring_x1::spsc::v4::segment_size(slot, $depth);
420	        let mut $store =
421	            region(size_of::<zc_ring_x1::PoolHeader>() as u64 + buf * $segments as u64);
422	        let mut $pool = Pool::init($store.as_mut_bytes(), buf as u32, $segments)
423	            .unwrap(); // OK: the region is sized for exactly the segments and line-aligned
424	        let ring = zc_ring_x1::spsc::v4::Ring::init(&mut $pool, slot, $depth, $segments)
425	            .unwrap(); // OK: the pool holds exactly the segments, sized by segment_size
426	        let mut $producer = ring.claim_producer(1).unwrap(); // OK: a fresh ring, no role held
427	        let mut $consumer = ring.claim_consumer(2).unwrap(); // OK: a fresh ring, no role held
428	    };
429	}
