431	/// Define the SPSC one-message loops over the ring `$pair` builds
432	/// (see `spsc_pair`): `$one_t`
433	/// moves COUNT messages single thread, pinned to the base cpu, and
434	/// `$two_t` moves them producer-thread -> consumer-thread (`pin`
435	/// as in [`spsc_ring_one_msg_2t`]), both over a ring of `depth`
436	/// slots. Each returns elapsed seconds. The SPSC versions share
437	/// the endpoint surface and differ by path, so one body serves
438	/// them all and the lines read as the protocol seam alone.
439	///
440	/// The 1t loop runs in a scoped thread rather than pinning the
441	/// main thread: spawned threads inherit the main thread's
442	/// affinity mask, which would squeeze every later part onto
443	/// the base cpu.
444	macro_rules! spsc_loops {
445	    ($one_t:ident, $two_t:ident, $($pair:tt)+) => {
446	        fn $one_t(depth: u32) -> f64 {
447	            spsc_pair!(producer, consumer, store, pool, depth, $($pair)+);
448	
449	            let start = Instant::now();
450	            std::thread::scope(|s| {
451	                s.spawn(move || {
452	                    pin_to_cpu(base_cpu());
453	                    for i in 0..COUNT {
454	                        match producer.reserve_slot_with::<Msg>(|_| false) {
455	                            Ok(mut slot) => {
456	                                slot.seq = i;
457	                                slot.commit();
458	                            }
459	                            Err(Full) => {
460	                                panic!(concat!(
461	                                    stringify!($one_t),
462	                                    ": producer Full SHOULD NOT HAPPEN"
463	                                ));
464	                            }
465	                        }
466	                        match consumer.reserve_slot_with::<Msg>(|_| false) {
467	                            Ok(msg) => {
468	                                assert_eq!(msg.seq, i);
469	                                msg.release();
470	                            }
471	                            Err(Empty) => {
472	                                panic!(concat!(
473	                                    stringify!($one_t),
474	                                    ": consumer Empty SHOULD NOT HAPPEN"
475	                                ));
476	                            }
477	                        }
478	                    }
479	                });
480	            });
481	            start.elapsed().as_secs_f64()
482	        }
483	
484	        fn $two_t(pin: PinPair, depth: u32) -> f64 {
485	            spsc_pair!(producer, consumer, store, pool, depth, $($pair)+);
486	
487	            let start = Instant::now();
488	            std::thread::scope(|s| {
489	                s.spawn(move || {
490	                    if let Some((p, _)) = pin {
491	                        pin_to_cpu(p);
492	                    }
493	                    for i in 0..COUNT {
494	                        let mut slot = producer.reserve_slot_with::<Msg>(policy::spin).unwrap(); // OK: policy::spin never gives up
495	                        slot.seq = i;
496	                        slot.commit();
497	                    }
498	                });
499	                s.spawn(move || {
500	                    if let Some((_, c)) = pin {
501	                        pin_to_cpu(c);
502	                    }
503	                    for i in 0..COUNT {
504	                        let msg = consumer.reserve_slot_with::<Msg>(policy::spin).unwrap(); // OK: policy::spin never gives up
505	                        assert_eq!(msg.seq, i);
506	                        msg.release();
507	                    }
508	                });
509	            });
510	            start.elapsed().as_secs_f64()
511	        }
512	    };
513	}
