1381	/// The lagging consumer: the producer streams COUNT messages
1382	/// spinning, the consumer reads two segments' worth and pauses
1383	/// [`LAG_PAUSE`], so the producer runs ahead across segments at
1384	/// every pause and the ring is Full only when every segment is.
1385	/// Its pace is the consumer's pauses, so it returns no time:
1386	/// segments used and both switch counts.
1387	macro_rules! lagging_2t {
1388	    ($name:ident, $send:ident, $recv:ident, $($pair:tt)+) => {
1389	        fn $name(pin: PinPair, segments: u32, depth: u32) -> (u32, (u64, u64)) {
1390	            let burst = 2 * depth as u64;
1391	            $($pair)+!(producer, consumer, store, pool, depth, segmented segments);
1392	            let (used, sent) = std::thread::scope(|s| {
1393	                let producer = s.spawn(move || {
1394	                    if let Some((p, _)) = pin {
1395	                        pin_to_cpu(p);
1396	                    }
1397	                    let mut used = 1u32 << producer.segment();
1398	                    for i in 0..COUNT {
1399	                        $send!(producer, i);
1400	                        used |= 1 << producer.segment();
1401	                    }
1402	                    (used, producer.switches())
1403	                });
1404	                let consumer = &mut consumer;
1405	                s.spawn(move || {
1406	                    if let Some((_, c)) = pin {
1407	                        pin_to_cpu(c);
1408	                    }
1409	                    let mut i = 0u64;
1410	                    while i < COUNT {
1411	                        let n = burst.min(COUNT - i);
1412	                        for j in i..i + n {
1413	                            $recv!(consumer, j);
1414	                        }
1415	                        i += n;
1416	                        std::thread::sleep(LAG_PAUSE);
1417	                    }
1418	                });
1419	                producer.join().unwrap() // OK: a panic in the loop is the demo's failure
1420	            });
1421	            assert!(
1422	                consumer.reserve_slot_with::<Msg>(|_| false).is_err(),
1423	                concat!(stringify!($name), ": not drained")
1424	            );
1425	            (used.count_ones(), (sent, consumer.switches()))
1426	        }
1427	    };
1428	}
