1430	/// The stream: the producer and the consumer on their own
1431	/// threads, both spinning, COUNT messages through a ring of
1432	/// `segments` by `depth`, the two_t loops' shape with the
1433	/// switches counted. Returns seconds, segments used, and both
1434	/// switch counts.
1435	macro_rules! stream_2t {
1436	    ($name:ident, $send:ident, $recv:ident, $($pair:tt)+) => {
1437	        fn $name(pin: PinPair, segments: u32, depth: u32) -> (f64, u32, (u64, u64)) {
1438	            $($pair)+!(producer, consumer, store, pool, depth, segmented segments);
1439	            let start = Instant::now();
1440	            let (used, sent) = std::thread::scope(|s| {
1441	                let producer = s.spawn(move || {
1442	                    if let Some((p, _)) = pin {
1443	                        pin_to_cpu(p);
1444	                    }
1445	                    let mut used = 1u32 << producer.segment();
1446	                    for i in 0..COUNT {
1447	                        $send!(producer, i);
1448	                        used |= 1 << producer.segment();
1449	                    }
1450	                    (used, producer.switches())
1451	                });
1452	                let consumer = &mut consumer;
1453	                s.spawn(move || {
1454	                    if let Some((_, c)) = pin {
1455	                        pin_to_cpu(c);
1456	                    }
1457	                    for i in 0..COUNT {
1458	                        $recv!(consumer, i);
1459	                    }
1460	                });
1461	                producer.join().unwrap() // OK: a panic in the loop is the demo's failure
1462	            });
1463	            let secs = start.elapsed().as_secs_f64();
1464	            (secs, used.count_ones(), (sent, consumer.switches()))
1465	        }
1466	    };
1467	}
