1469	/// One SPSC send, spinning: reserve, write, commit.
1470	macro_rules! spsc_send {
1471	    ($producer:ident, $i:expr) => {{
1472	        let mut slot = $producer.reserve_slot_with::<Msg>(policy::spin).unwrap(); // OK: policy::spin never gives up
1473	        slot.seq = $i;
1474	        slot.commit();
1475	    }};
1476	}
