1478	/// One MPSC send, spinning: the closure fill.
1479	macro_rules! mpsc_send {
1480	    ($producer:ident, $i:expr) => {{
1481	        $producer
1482	            .send_with::<Msg>(policy::spin, |m| m.seq = $i)
1483	            .unwrap(); // OK: policy::spin never gives up
1484	    }};
1485	}
