1487	/// One receive, spinning, the sequence asserted: the endpoint
1488	/// surface both consumers share.
1489	macro_rules! ring_recv {
1490	    ($consumer:ident, $i:expr) => {{
1491	        let msg = $consumer.reserve_slot_with::<Msg>(policy::spin).unwrap(); // OK: policy::spin never gives up
1492	        assert_eq!(msg.seq, $i);
1493	        msg.release();
1494	    }};
1495	}
