1520	/// The two shapes the switch cost is a difference between: the
1521	/// same 32 slots as one segment, which never switches, and as 32
1522	/// segments of one slot, which switches on nearly every message.
1523	const COST_SHAPES: [(u32, u32); 2] = [(1, 32), (32, 1)];
1524	
1525	/// Run a pair of [`COST_SHAPES`] lines through `run`, push both
1526	/// rows, and put the cost of one switch, the gap in ns per
1527	/// message over the gap in switches per message, on the second.
1528	fn switch_cost(
1529	    rows: &mut Vec<StressRow>,
1530	    line: &str,
1531	    placement: &str,
1532	    mut run: impl FnMut(u32, u32) -> (f64, u32, (u64, u64)),
1533	) {
1534	    let mut pair: Vec<StressRow> = COST_SHAPES
1535	        .iter()
1536	        .map(|&(segments, depth)| {
1537	            let (secs, used, (sent, seen)) = run(segments, depth);
1538	            assert_eq!(sent, seen, "{line}: switch counts differ");
1539	            StressRow {
1540	                line: line.to_string(),
1541	                placement: placement.to_string(),
1542	                shape: format!("{segments}x{depth}"),
1543	                ns: Some(secs * 1e9 / COUNT as f64),
1544	                used: (used, segments),
1545	                switches: sent,
1546	                switch_ns: None,
1547	            }
1548	        })
1549	        .collect();
1550	    let (a, b) = (&pair[0], &pair[1]);
1551	    let cost = (b.ns.unwrap_or(0.0) - a.ns.unwrap_or(0.0)) / (b.per_msg() - a.per_msg()); // OK: both ns are Some, set just above
1552	    pair[1].switch_ns = Some(cost);
1553	    rows.append(&mut pair);
1554	}
