1578	         of {DEPTH} slots, then the switch cost at depth 1",
1579	        commas(COUNT)
1580	    );
1581	    println!();
1582	    let mut rows = Vec::new();
1583	    let shape = format!("{STRESS_SEGMENTS}x{DEPTH}");
1584	    for (line, run) in [
1585	        (
1586	            "spsc3 burst 1t",
1587	            spsc3_burst_1t as fn(u32, u32) -> (f64, u32, (u64, u64)),
1588	        ),
1589	        ("spsc4 burst 1t", spsc4_burst_1t),
1590	        ("mpsc2 burst 1t", mpsc2_burst_1t),
1591	        ("mpsc3 burst 1t", mpsc3_burst_1t),
1592	    ] {
1593	        let (secs, used, (sent, seen)) = run(STRESS_SEGMENTS, DEPTH);
1594	        assert_eq!(sent, seen, "{line}: switch counts differ");
1595	        rows.push(StressRow {
1596	            line: line.to_string(),
1597	            placement: format!("core {}", base_cpu()),
1598	            shape: shape.clone(),
1599	            ns: Some(secs * 1e9 / COUNT as f64),
1600	            used: (used, STRESS_SEGMENTS),
1601	            switches: sent,
1602	            switch_ns: None,
1603	        });
1604	    }
1605	    for Placement {
1606	        label: placement,
1607	        pin,
1608	    } in placements
1609	    {
1610	        for (line, run) in [
1611	            (
1612	                "spsc3 lagging 2t",
1613	                spsc3_lagging_2t as fn(PinPair, u32, u32) -> (u32, (u64, u64)),
1614	            ),
1615	            ("spsc4 lagging 2t", spsc4_lagging_2t),
1616	            ("mpsc2 lagging 2t", mpsc2_lagging_2t),
1617	            ("mpsc3 lagging 2t", mpsc3_lagging_2t),
1618	        ] {
1619	            let (used, (sent, seen)) = run(*pin, STRESS_SEGMENTS, DEPTH);
1620	            assert_eq!(sent, seen, "{line}: switch counts differ");
1621	            rows.push(StressRow {
1622	                line: line.to_string(),
1623	                placement: placement.clone(),
1624	                shape: shape.clone(),
1625	                ns: None,
1626	                used: (used, STRESS_SEGMENTS),
1627	                switches: sent,
1628	                switch_ns: None,
1629	            });
1630	        }
1631	    }
1632	    let one_t = format!("core {}", base_cpu());
1633	    switch_cost(&mut rows, "spsc3 burst 1t", &one_t, spsc3_burst_1t);
1634	    switch_cost(&mut rows, "spsc4 burst 1t", &one_t, spsc4_burst_1t);
1635	    switch_cost(&mut rows, "mpsc2 burst 1t", &one_t, mpsc2_burst_1t);
1636	    switch_cost(&mut rows, "mpsc3 burst 1t", &one_t, mpsc3_burst_1t);
1637	    // The stream across cores at the farthest placement the
1638	    // machine has, x-CCX, else CCX, else unpinned.
1639	    let Placement {
1640	        label: placement,
1641	        pin,
1642	    } = placements
1643	        .iter()
1644	        .find(|p| p.label.ends_with(" x-CCX"))
1645	        .or_else(|| placements.iter().find(|p| p.label.ends_with(" CCX")))
1646	        .unwrap_or_else(|| &placements[placements.len() - 1]);
1647	    let (placement, pin) = (placement.clone(), *pin);
1648	    switch_cost(
1649	        &mut rows,
1650	        "spsc3 stream 2t",
