1694	    legend(
1695	        "switch ns: the cost of one switch, the gap in ns/msg between the two shapes over the gap \
1696	         in sw/msg, on the 32x1 row. Single-threaded it is the instructions alone. Streaming across \
1697	         cores it includes the cold segment crossing.",
1698	    );
1699	}
