1709	/// Run every flavor at every depth of [`DEPTHS`] at each
1710	/// placement the machine offers, and print one markdown table
1711	/// per placement, ns per message in the depth columns.
1712	///
1713	/// - The same loops as the lines above, so a `d=64` cell and
1714	///   the matching line agree up to run noise.
1715	/// - Depth 1 is lockstep: every message is its own handoff, so
1716	///   streaming there costs what a round trip does.
1717	fn depth_sweep(two_t: &[Placement]) {
1718	    let mut placements = vec![(format!("1t core {}", base_cpu()), SweepPlacement::OneT)];
1719	    for Placement { label, pin } in two_t {
1720	        placements.push((format!("2t {label}"), SweepPlacement::TwoT(*pin)));
1721	    }
1722	    let depth_list: Vec<String> = DEPTHS.iter().map(|d| d.to_string()).collect();
1723	    println!(
1724	        "depth sweep: {} messages per cell, ns/msg at depths {}, spsc-v3, spsc-v4, mpsc-v2, and mpsc-v3 with {SWEEP_SEGMENTS} segment(s)",
1725	        commas(COUNT),
1726	        depth_list.join(", ")
1727	    );
1728	    for (label, placement) in &placements {
1729	        println!();
1730	        let mut header = format!("| {label:<22} |");
1731	        let mut sep = format!("|{}|", "-".repeat(24));
1732	        for d in &depth_list {
1733	            header.push_str(&format!(" {:>7} |", format!("d={d}")));
1734	            sep.push_str(&format!("{}:|", "-".repeat(8)));
1735	        }
1736	        println!("{header}");
1737	        println!("{sep}");
1738	        for flavor in &STREAM_FLAVORS {
1739	            let mut row = format!("| {:<22} |", flavor.name);
1740	            for &depth in &DEPTHS {
1741	                if depth < flavor.min_depth {
1742	                    row.push_str(&format!(" {:>7} |", "-"));
1743	                    continue;
1744	                }
1745	                let secs = match placement {
1746	                    SweepPlacement::OneT => (flavor.one_t)(depth),
1747	                    SweepPlacement::TwoT(pin) => (flavor.two_t)(*pin, depth),
1748	                };
1749	                row.push_str(&format!(" {:>7.1} |", secs * 1e9 / COUNT as f64));
1750	            }
1751	            println!("{row}");
1752	        }
1753	    }
1754	}
