fn main() {
    let banner = concat!(env!("CARGO_PKG_NAME"), " ", env!("CARGO_PKG_VERSION"));
    println!("{banner}");
    let base = match parse_args(std::env::args().skip(1)) {
        Args::Run { base_cpu } => base_cpu,
        Args::Exit { code } => std::process::exit(code),
    };
